<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import PermissionChecklist from '@/Components/Wedding/PermissionChecklist.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, ref, watch } from 'vue';
interface EventItem { id:number; name:string; type:string; event_date:string|null; event_time:string|null; venue:string|null; address:string|null; is_primary:boolean }
interface Service { id:number; wedding_service_template_id:number|null; name:string; owner:string; status:string; estimated_cost:string|null }
interface Responsibility { id:number; label:string; owner:string; status:string; due_date:string|null; notes:string|null }
interface Member { id:number; relationship:string; permissions:Record<string,boolean>|null; user:{name:string} }
interface Wedding { id:number; name:string; status:string; support_type:string; timezone:string; authorized_capacity:number|null; interview:{status:string}|null; events:EventItem[]; services:Service[]; responsibilities:Responsibility[]; memberships:Member[] }
const props=defineProps<{wedding:Wedding;canEdit:boolean;serviceTemplates:{id:number;name:string;default_owner:string}[]}>();
const normalizeDate=(value:string|null)=>value?value.slice(0,10):'';
const formatDate=(value:string|null)=>{const date=normalizeDate(value);return date?new Intl.DateTimeFormat('es-MX',{dateStyle:'long',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`)):'Fecha pendiente';};
const events=ref<EventItem[]>([]); watch(()=>props.wedding.events,(items)=>events.value=items.map(i=>({...i,event_date:normalizeDate(i.event_date),event_time:i.event_time?.slice(0,5)??''})),{immediate:true,deep:true});
const eventErrors=ref<Record<number,string>>({});
const primaryEvent=computed(()=>events.value.find(event=>event.is_primary)??events.value[0]);
const weddingForm=useForm({name:props.wedding.name,status:props.wedding.status,support_type:props.wedding.support_type,authorized_capacity:props.wedding.authorized_capacity as number|null,timezone:props.wedding.timezone}); const editingWedding=ref(false);
const serviceForm=useForm({wedding_service_template_id:null as number|null,name:'',owner:'company',status:'included',estimated_cost:null as number|null}); const serviceEditForm=useForm({wedding_service_template_id:null as number|null,name:'',owner:'company',status:'included',estimated_cost:null as number|null}); const editingService=ref<number|null>(null);
const responsibilityForm=useForm({label:'',owner:'company',due_date:'',notes:''}); const responsibilityEditForm=useForm({label:'',owner:'company',status:'pending',due_date:'',notes:''}); const editingResponsibility=ref<number|null>(null);
const ownerLabel:Record<string,string>={company:'Empresa',couple:'Pareja',shared:'Compartida'}; const supportLabel:Record<string,string>={full:'Integral',shared:'Compartida',advisory:'Asesoría'}; const statusLabel:Record<string,string>={included:'Incluido',pending:'Pendiente',confirmed:'Confirmado',cancelled:'Cancelado',in_progress:'En proceso',completed:'Completada'};
const visit={preserveScroll:true,preserveState:true,replace:true};
function saveWedding(){weddingForm.patch(route('weddings.update',props.wedding.id),{...visit,onSuccess:()=>editingWedding.value=false});}
function saveEvent(event:EventItem){router.put(route('weddings.events.update',[props.wedding.id,event.id]),event,{...visit,onSuccess:()=>delete eventErrors.value[event.id],onError:errors=>eventErrors.value[event.id]=Object.values(errors).join(' ')});}
function deleteEvent(event:EventItem){if(confirm(`¿Eliminar el evento “${event.name}”?`))router.delete(route('weddings.events.destroy',[props.wedding.id,event.id]),visit);}
function templateFor(form:typeof serviceForm|typeof serviceEditForm){const template=props.serviceTemplates.find(item=>item.id===form.wedding_service_template_id);if(template){form.name=template.name;form.owner=template.default_owner;}}
function addService(){serviceForm.post(route('weddings.services.store',props.wedding.id),{...visit,onSuccess:()=>serviceForm.reset()});} function editService(item:Service){editingService.value=item.id;Object.assign(serviceEditForm,{wedding_service_template_id:item.wedding_service_template_id,name:item.name,owner:item.owner,status:item.status,estimated_cost:item.estimated_cost===null?null:Number(item.estimated_cost)});} function saveService(item:Service){serviceEditForm.patch(route('weddings.services.update',[props.wedding.id,item.id]),{...visit,onSuccess:()=>{editingService.value=null;serviceEditForm.reset();}});} function deleteService(item:Service){if(confirm(`¿Eliminar el servicio “${item.name}”?`))router.delete(route('weddings.services.destroy',[props.wedding.id,item.id]),visit);}
function addResponsibility(){responsibilityForm.post(route('weddings.responsibilities.store',props.wedding.id),{...visit,onSuccess:()=>responsibilityForm.reset()});} function editResponsibility(item:Responsibility){editingResponsibility.value=item.id;Object.assign(responsibilityEditForm,{label:item.label,owner:item.owner,status:item.status,due_date:normalizeDate(item.due_date),notes:item.notes??''});} function saveResponsibility(item:Responsibility){responsibilityEditForm.patch(route('weddings.responsibilities.update',[props.wedding.id,item.id]),{...visit,onSuccess:()=>{editingResponsibility.value=null;responsibilityEditForm.reset();}});} function deleteResponsibility(item:Responsibility){if(confirm(`¿Eliminar la responsabilidad “${item.label}”?`))router.delete(route('weddings.responsibilities.destroy',[props.wedding.id,item.id]),visit);}
</script>
<template><Head :title="`Expediente · ${wedding.name}`"/><AuthenticatedLayout><template #header><div><Link :href="route('dashboard')" class="text-sm text-rose-800 underline">← Inicio</Link><h1 class="mt-1 font-serif text-3xl">Expediente · {{ wedding.name }}</h1><p class="mt-1 text-sm text-stone-600">Gestiona la boda; el menú global contiene las demás áreas.</p></div></template><main class="mx-auto max-w-6xl space-y-6 px-4 py-8">
<section class="rounded-2xl bg-stone-800 p-6 text-white"><p class="text-sm uppercase tracking-[.2em] text-rose-200">Evento principal · {{ wedding.timezone }}</p><h2 class="mt-2 font-serif text-3xl">{{ primaryEvent?.name||'Evento por definir' }}</h2><p class="mt-2 text-stone-200">{{ formatDate(primaryEvent?.event_date??null) }} · {{ primaryEvent?.venue||'Lugar pendiente' }}</p></section>
<div class="grid gap-6 lg:grid-cols-2"><section class="rounded-2xl border border-stone-200 bg-white p-6"><h2 class="font-serif text-2xl">Eventos</h2><p class="mt-1 text-sm text-stone-600">Usa “evento principal” para definir cuál se muestra en el centro.</p><div v-for="event in events" :key="event.id" class="mt-5 border-t pt-4"><form v-if="canEdit" class="grid gap-3 sm:grid-cols-2" @submit.prevent="saveEvent(event)"><label class="text-sm">Nombre<input v-model="event.name" required class="mt-1 w-full rounded-lg border-stone-300"/></label><label class="text-sm">Tipo<select v-model="event.type" class="mt-1 w-full rounded-lg border-stone-300"><option value="reception">Recepción</option><option value="ceremony">Ceremonia</option><option value="civil">Civil</option><option value="after_party">Tornaboda</option><option value="other">Otro</option></select></label><label class="text-sm">Fecha<input v-model="event.event_date" type="date" class="mt-1 w-full rounded-lg border-stone-300"/></label><label class="text-sm">Hora<input v-model="event.event_time" type="time" class="mt-1 w-full rounded-lg border-stone-300"/></label><label class="text-sm sm:col-span-2">Lugar<input v-model="event.venue" class="mt-1 w-full rounded-lg border-stone-300"/></label><label class="flex items-center gap-2 text-sm sm:col-span-2"><input v-model="event.is_primary" type="checkbox"/> Evento principal</label><p v-if="eventErrors[event.id]" class="text-sm text-red-700 sm:col-span-2">{{ eventErrors[event.id] }}</p><div class="flex gap-3"><button class="rounded-lg border border-rose-700 px-3 py-2 text-sm text-rose-800">Guardar evento</button><button type="button" class="text-sm text-red-700 underline" @click="deleteEvent(event)">Eliminar</button></div></form><div v-else><b>{{ event.name }}</b><p class="text-sm">{{ formatDate(event.event_date) }}</p></div></div><Link v-if="canEdit" :href="route('weddings.events.create',wedding.id)" class="mt-5 inline-block text-sm text-rose-800 underline">+ Crear otro evento</Link></section>
<section class="rounded-2xl border border-stone-200 bg-white p-6"><div class="flex justify-between gap-3"><h2 class="font-serif text-2xl">Configuración</h2><button v-if="canEdit" type="button" class="text-sm text-rose-800 underline" @click="editingWedding=!editingWedding">{{editingWedding?'Cancelar':'Editar expediente'}}</button></div><form v-if="canEdit&&editingWedding" class="mt-4 grid gap-3 sm:grid-cols-2" @submit.prevent="saveWedding"><label class="text-sm">Nombre<input v-model="weddingForm.name" required class="mt-1 w-full rounded border-stone-300"/></label><label class="text-sm">Estado<select v-model="weddingForm.status" class="mt-1 w-full rounded border-stone-300"><option value="consultation">Consulta</option><option value="contracted">Contratada</option><option value="preparation">Preparación</option></select></label><label class="text-sm">Acompañamiento<select v-model="weddingForm.support_type" class="mt-1 w-full rounded border-stone-300"><option value="full">Integral</option><option value="shared">Compartida</option><option value="advisory">Asesoría</option></select></label><label class="text-sm">Cupo autorizado<input v-model.number="weddingForm.authorized_capacity" type="number" min="1" class="mt-1 w-full rounded border-stone-300"/></label><label class="text-sm sm:col-span-2">Zona horaria<input v-model="weddingForm.timezone" required class="mt-1 w-full rounded border-stone-300"/></label><button class="justify-self-start rounded bg-rose-800 px-3 py-2 text-sm text-white">Guardar expediente</button></form><dl v-else class="mt-4 space-y-3 text-sm"><div class="flex justify-between"><dt>Acompañamiento</dt><dd>{{ownerLabel[wedding.support_type]??wedding.support_type}}</dd></div><div class="flex justify-between"><dt>Cupo autorizado</dt><dd>{{wedding.authorized_capacity??'Pendiente'}}</dd></div><div class="flex justify-between"><dt>Configuración</dt><dd>{{wedding.interview?.status==='active'?'Activa':'Borrador'}}</dd></div></dl><Link v-if="canEdit&&wedding.interview?.status!=='active'" :href="route('weddings.interview.edit',wedding.id)" class="mt-6 inline-block rounded-lg bg-rose-800 px-4 py-2 text-sm text-white">Revisar entrevista antes de activar</Link><button v-if="canEdit&&wedding.interview?.status!=='active'" class="ml-2 mt-6 rounded-lg border border-rose-700 px-4 py-2 text-sm text-rose-800" @click="router.post(route('weddings.configuration.activate',wedding.id),{},visit)">Activar configuración revisada</button></section></div>
<div class="grid gap-6 lg:grid-cols-2"><section class="rounded-2xl border border-stone-200 bg-white p-6"><h2 class="font-serif text-2xl">Servicios contratados</h2><article v-for="service in wedding.services" :key="service.id" class="mt-4 border-t pt-3 text-sm"><form v-if="editingService===service.id" class="grid gap-2" @submit.prevent="saveService(service)"><label>Catálogo<select v-model="serviceEditForm.wedding_service_template_id" class="mt-1 w-full rounded border-stone-300" @change="templateFor(serviceEditForm)"><option :value="null">Servicio personalizado</option><option v-for="item in serviceTemplates" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>Servicio<input v-model="serviceEditForm.name" required class="mt-1 w-full rounded border-stone-300"/></label><div class="grid grid-cols-2 gap-2"><select v-model="serviceEditForm.owner" class="rounded border-stone-300"><option value="company">Empresa</option><option value="couple">Pareja</option><option value="shared">Compartida</option></select><select v-model="serviceEditForm.status" class="rounded border-stone-300"><option value="included">Incluido</option><option value="pending">Pendiente</option><option value="confirmed">Confirmado</option><option value="cancelled">Cancelado</option></select></div><label>Costo estimado<input v-model.number="serviceEditForm.estimated_cost" type="number" min="0" class="mt-1 w-full rounded border-stone-300"/></label><div><button class="rounded bg-rose-800 px-3 py-1 text-white">Guardar</button><button type="button" class="ml-2 underline" @click="editingService=null">Cancelar</button></div></form><div v-else><b>{{service.name}}</b><p>{{ownerLabel[service.owner]}} · {{statusLabel[service.status]}}<span v-if="service.estimated_cost"> · ${{service.estimated_cost}}</span></p><button v-if="canEdit" class="mt-2 text-rose-800 underline" @click="editService(service)">Editar</button><button v-if="canEdit" class="ml-3 text-red-700 underline" @click="deleteService(service)">Eliminar</button></div></article><form v-if="canEdit&&editingService===null" class="mt-5 grid gap-3 border-t pt-4" @submit.prevent="addService"><h3 class="font-medium">Agregar servicio</h3><label>Catálogo de servicios<select v-model="serviceForm.wedding_service_template_id" class="mt-1 w-full rounded-lg border-stone-300" @change="templateFor(serviceForm)"><option :value="null">Servicio personalizado</option><option v-for="item in serviceTemplates" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>Nombre del servicio<input v-model="serviceForm.name" required class="mt-1 w-full rounded-lg border-stone-300"/></label><div class="grid grid-cols-2 gap-2"><label>Responsable<select v-model="serviceForm.owner" class="mt-1 w-full rounded-lg border-stone-300"><option value="company">Empresa</option><option value="couple">Pareja</option><option value="shared">Compartida</option></select></label><label>Estado<select v-model="serviceForm.status" class="mt-1 w-full rounded-lg border-stone-300"><option value="included">Incluido</option><option value="pending">Pendiente</option><option value="confirmed">Confirmado</option></select></label></div><label>Costo estimado<input v-model.number="serviceForm.estimated_cost" type="number" min="0" class="mt-1 w-full rounded-lg border-stone-300"/></label><button class="justify-self-start rounded-lg border border-rose-700 px-3 py-2 text-sm text-rose-800">Agregar servicio</button></form></section>
<section class="rounded-2xl border border-stone-200 bg-white p-6"><h2 class="font-serif text-2xl">Responsabilidades</h2><p class="mt-1 text-sm text-stone-600">La fecha límite es una referencia para el cronograma y alertas; no cambia la fecha de la boda.</p><article v-for="item in wedding.responsibilities" :key="item.id" class="mt-4 border-t pt-3 text-sm"><form v-if="editingResponsibility===item.id" class="grid gap-2" @submit.prevent="saveResponsibility(item)"><label>Responsabilidad<input v-model="responsibilityEditForm.label" required class="mt-1 w-full rounded border-stone-300"/></label><div class="grid grid-cols-2 gap-2"><select v-model="responsibilityEditForm.owner" class="rounded border-stone-300"><option value="company">Empresa</option><option value="couple">Pareja</option><option value="shared">Compartida</option></select><select v-model="responsibilityEditForm.status" class="rounded border-stone-300"><option value="pending">Pendiente</option><option value="in_progress">En proceso</option><option value="completed">Completada</option><option value="cancelled">Cancelada</option></select></div><label>Fecha límite<input v-model="responsibilityEditForm.due_date" type="date" class="mt-1 w-full rounded border-stone-300"/></label><textarea v-model="responsibilityEditForm.notes" class="rounded border-stone-300" placeholder="Notas"/><div><button class="rounded bg-rose-800 px-3 py-1 text-white">Guardar</button><button type="button" class="ml-2 underline" @click="editingResponsibility=null">Cancelar</button></div></form><div v-else><b>{{item.label}}</b><p>{{ownerLabel[item.owner]}} · {{statusLabel[item.status]}} · {{formatDate(item.due_date)}}</p><p v-if="item.notes">{{item.notes}}</p><button v-if="canEdit" class="mt-2 text-rose-800 underline" @click="editResponsibility(item)">Editar</button><button v-if="canEdit" class="ml-3 text-red-700 underline" @click="deleteResponsibility(item)">Eliminar</button></div></article><form v-if="canEdit&&editingResponsibility===null" class="mt-5 grid gap-3 border-t pt-4" @submit.prevent="addResponsibility"><h3 class="font-medium">Agregar responsabilidad</h3><label>Responsabilidad<input v-model="responsibilityForm.label" required class="mt-1 w-full rounded-lg border-stone-300"/></label><label>Responsable<select v-model="responsibilityForm.owner" class="mt-1 w-full rounded-lg border-stone-300"><option value="company">Empresa</option><option value="couple">Pareja</option><option value="shared">Compartida</option></select></label><label>Fecha límite (opcional)<input v-model="responsibilityForm.due_date" type="date" class="mt-1 w-full rounded-lg border-stone-300"/></label><label>Notas<textarea v-model="responsibilityForm.notes" class="mt-1 w-full rounded-lg border-stone-300"/></label><button class="justify-self-start rounded-lg border border-rose-700 px-3 py-2 text-sm text-rose-800">Agregar responsabilidad</button></form></section></div>
<PermissionChecklist :wedding-id="wedding.id" :memberships="wedding.memberships" :editable="canEdit" />
</main></AuthenticatedLayout></template>
